<style>.item-head{margin-top:24px;margin-bottom:12px}.quote-item{margin-bottom:12px}.totals{margin-top:16px}</style><script>(()=>{const box=document.getElementById('items'),discount=document.getElementById('discount'),fmt=n=>new Intl.NumberFormat('es-CL').format(Math.max(n,0));function reindex(){box.querySelectorAll('.quote-item').forEach((row,i)=>{row.querySelectorAll('[name]').forEach(f=>f.name=f.name.replace(/items\[\d+\]/,`items[${i}]`));row.querySelector('.remove').style.display=i?'inline-flex':'none'})}function calc(){let sum=0;box.querySelectorAll('.quote-item').forEach(row=>{const q=Number(row.querySelector('[name$="[quantity]"]').value||0),p=Number(row.querySelector('[name$="[unit_price]"]').value||0);row.querySelector('.subtotal').textContent=fmt(q*p);sum+=q*p});const net=Math.max(sum-Number(discount.value||0),0),tax=Math.round(net*.19);document.getElementById('net').textContent=fmt(net);document.getElementById('tax').textContent=fmt(tax);document.getElementById('total').textContent=fmt(net+tax)}document.getElementById('add-item').onclick=()=>{box.insertAdjacentHTML('beforeend',document.getElementById('item-template').innerHTML.replaceAll('__I__',box.children.length));reindex();calc()};box.addEventListener('input',calc);box.addEventListener('click',e=>{if(e.target.classList.contains('remove')){e.target.closest('.quote-item').remove();reindex();calc()}});discount.addEventListener('input',calc);reindex();calc()})()</script>
